-- Report #209 / #184 data half, FULLY corrected. The previous version of
-- this file inserted float-typed columns (Speed, EffectRealPointsPerLevel_1)
-- as raw float BIT PATTERNS (e.g. 1101004800 instead of 20.0, 1082130432
-- instead of 4.0), so the live spell_dbc rows carried billion-scale values --
-- Lightning Bolt damage/speed exploded (report #209, re-report of #184).
-- ChainTarget=3 also sat on the empty effect slot 2 instead of effect 1 (the
-- SCHOOL_DAMAGE effect).
-- Rebuilt by struct-parsing env/dist/data/dbc/Spell.dbc and diffing EVERY
-- column against this row (floats emitted as real floats, ChainTargets on
-- the damage effect). Idempotent: DELETE then INSERT.
-- NOTE: live broken rows are repaired by rev_chain_lightning_repair.sql
-- (this file's hash change does not guarantee a re-run).

DELETE FROM `spell_dbc` WHERE `ID` IN (49238, 49239, 49240);
